/*
 * Table density (optional pattern `table-density`, docs/optional/table-density.md).
 * `data-density="compact"` on <html> (the user's preference, set like
 * `high-contrast`) or on any container tightens table rows by 8px (a text row from 37px to 29px).
 * Controls inside cells keep their own size, so targets stay at least 24px
 * (WCAG 2.5.8).
 */
[data-density='compact'] [data-slot='table-head'] {
    height: 2rem;
}

[data-density='compact'] [data-slot='table-cell'] {
    padding-block: 0.25rem;
}

/*
 * Scroll cue (core list pattern, docs/list-page.md). A scroller that hides
 * columns fades its content out over the last 2rem on that side, so a phone
 * user sees that the table continues. `useScrollRegion` (Table, TablePanel)
 * sets `data-scroll-cue-left` / `data-scroll-cue-right` only while content is
 * hidden there, so tables that fit are untouched.
 *
 * A mask instead of a shadow: it uses no colour at all (`black` below is mask
 * alpha, not a colour), so it is right on every surface in light, dark and
 * high contrast, and sticky or hovered rows cannot cover it. The vertical
 * scrollbar width (`--scroll-cue-scrollbar`) stays unmasked. Keyboard focus
 * drops the mask so the inset focus ring stays whole.
 * ponytail: in right-to-left layouts the vertical scrollbar can sit on the
 * left and gets faded there; flip the gradient with :dir(rtl) when an app
 * ships an RTL locale.
 */
@property --scroll-cue-left {
    syntax: '<length>';
    inherits: false;
    initial-value: 0px;
}

@property --scroll-cue-right {
    syntax: '<length>';
    inherits: false;
    initial-value: 0px;
}

[data-scroll-cue-left] {
    --scroll-cue-left: 2rem;
}

[data-scroll-cue-right] {
    --scroll-cue-right: 2rem;
}

[data-scroll-cue-left],
[data-scroll-cue-right] {
    mask-image: linear-gradient(
        to right,
        transparent,
        black var(--scroll-cue-left),
        black
            calc(
                100% - var(--scroll-cue-scrollbar, 0px) -
                    var(--scroll-cue-right)
            ),
        transparent calc(100% - var(--scroll-cue-scrollbar, 0px)),
        black calc(100% - var(--scroll-cue-scrollbar, 0px))
    );
}

[data-slot='table-container'],
[data-slot='table-panel-scroll'] {
    transition:
        --scroll-cue-left 150ms ease-out,
        --scroll-cue-right 150ms ease-out;
}

[data-scroll-cue-left]:focus-visible,
[data-scroll-cue-right]:focus-visible {
    mask-image: none;
}

@media (prefers-reduced-motion: reduce) {
    [data-slot='table-container'],
    [data-slot='table-panel-scroll'] {
        transition: none;
    }
}

html.reduce-motion [data-slot='table-container'],
html.reduce-motion [data-slot='table-panel-scroll'] {
    transition: none;
}
